{
  "packageManager": "yarn@4.18.0",
  "dependencies": {
    "@calcit/procs": "0.30.1-alpha.5"
  },
  "scripts": {
    "check-client": "calcit calcit.cirru --check-only --ns 'app.$meta' --ns app.client --ns app.comp.container --ns app.comp.login --ns app.comp.navigation --ns app.comp.profile --ns app.config --ns app.schema",
    "check-server": "calcit calcit.cirru --entry server --check-only --ns 'app.$meta' --ns app.config --ns app.schema --ns app.server --ns app.twig.container --ns app.twig.user --ns app.updater --ns app.updater.router --ns app.updater.session --ns app.updater.user",
    "compile-page": "calcit calcit.cirru js",
    "release-page": "vite build --base=${VITE_BASE_URL:-./}",
    "watch-page": "calcit calcit.cirru --watch"
  },
  "devDependencies": {
    "bottom-tip": "^0.1.3",
    "vite": "^8.2.2"
  },
  "version": "0.0.3"
}
